def cite(n):return f'<a class="cite" href="#s{n:02}" aria-label="출처 {n}">[{n}]</a>'
def money(value):return f'{value:,.0f}'
def span(values):return f'{money(values[0])}~{money(values[1])}'
def table(headers,rows,label):
    return f'<div class="table-wrap" tabindex="0" role="region" aria-label="{label}"><table><thead><tr>'+''.join(f'<th>{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

