css='''
.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:6px;margin:22px 0}.table-wrap:focus-visible{outline:3px solid var(--accent);outline-offset:4px}table{border-collapse:collapse;width:100%;min-width:580px;font-size:14px;line-height:1.8}th,td{padding:13px 14px;vertical-align:top;text-align:left;border-bottom:1px solid var(--line)}th{background:var(--soft);font-weight:750}tr:last-child td{border-bottom:0}td:first-child{font-weight:650}.sample-report{border:1px solid #c6d7ce;border-left:4px solid var(--accent);border-radius:5px;padding:23px;margin:24px 0}.sample-report h3{margin-top:9px}.sample-report .spec dd{margin-bottom:18px}.spec dt{font-size:14px;font-weight:750;color:var(--accent);margin:15px 0 5px}.spec dd{margin:0;font-size:16px;line-height:1.9}.key strong{font-weight:750}.detail-body table{font-size:13px}.header-bottom span{max-width:620px}.footer{margin-top:20px}
@media(max-width:760px){table{min-width:560px;font-size:13px}th,td{padding:11px}.sample-report{padding:18px}.spec dd{font-size:15px}.header-bottom span{font-size:12px}}
@media print{.table-wrap{overflow:visible}table{min-width:0;font-size:8.7pt}.detail-body table{font-size:8.5pt}th,td{padding:7px}tr{break-inside:avoid}.sample-report{break-inside:avoid}.spec dd{font-size:10pt}}
'''
html=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="B2B2C 기능평가 솔루션5개 후보의 가정 개발사양, 결과 산출 과정, 공개가격과 개발·운영비 비교"><title>B2B2C 솔루션 후보 — 개발 스펙·비용·결과 과정</title><style>{style}{css}</style></head><body><a class="skip" href="#main">본문으로 바로 가기</a><div class="page"><header class="header" id="top"><div class="project">인사이더스 · 린 프로젝트 개발 검토</div><h1>B2B2C 솔루션 후보<br>개발 스펙·비용·결과 과정</h1><p class="subtitle">기능평가 키트 · 측정 스테이션 · 병원 보조 · 운동 피드백 · 정기 서비스</p><div class="header-bottom"><span>2026.10.26 · 가정 명세 / 내부 개발원가 모델 · 금액 단위 별도 표시</span><button type="button" onclick="window.print()">인쇄 / PDF 저장</button></div></header><div class="layout"><aside class="sidebar"><nav aria-label="보고서 목차"><div class="nav-title">목차</div>{links}</nav><p class="nav-note">공개가격과 추정 예산을<br>구분했습니다.<br>상세 산식은8장에 있습니다.</p></aside><main id="main"><details class="mobile-nav"><summary>목차</summary><nav class="detail-body" aria-label="모바일 목차">{links}</nav></details>{''.join(sections)}<footer class="footer"><p>검증용 후보 명세다. 기술 성능·제품 분류·고객·구매 의향과 최종 개발 범위는 확정하지 않았다.</p><a href="#top">처음으로 ↑</a></footer></main></div></div><script>{script}</script></body></html>'''
